import {
  Field,
  FieldDescription,
  FieldGroup,
  FieldLabel,
  FieldSet,
} from "@/registry/erbium/ui/field";
import { Input } from "@/registry/erbium/ui/input";

export default function FieldInput() {
  return (
    <div className="w-full max-w-md">
      <FieldSet>
        <FieldGroup>
          <Field>
            <FieldLabel>Username</FieldLabel>
            <Input type="text" placeholder="Jane Doe" />
            <FieldDescription>Choose a unique username for your account.</FieldDescription>
          </Field>
          <Field>
            <FieldLabel>Password</FieldLabel>
            <FieldDescription>Must be at least 8 characters long.</FieldDescription>
            <Input type="password" placeholder="••••••••" />
          </Field>
        </FieldGroup>
      </FieldSet>
    </div>
  );
}

import { useState } from "react";

import { Field, FieldDescription, FieldLabel } from "@/registry/erbium/ui/field";
import { Slider } from "@/registry/erbium/ui/slider";

export default function FieldSlider() {
  const [value, setValue] = useState([200, 800]);
  return (
    <div className="w-full max-w-md">
      <Field>
        <FieldLabel>Price Range</FieldLabel>
        <FieldDescription>
          Set your budget range ($
          <span className="font-medium tabular-nums">{value[0]}</span> -{" "}
          <span className="font-medium tabular-nums">{value[1]}</span>).
        </FieldDescription>
        <Slider
          value={value}
          onValueChange={(next) => setValue(Array.isArray(next) ? [...next] : [next])}
          max={1000}
          min={0}
          step={10}
          className="mt-2 w-full"
          aria-label="Price Range"
        />
      </Field>
    </div>
  );
}

import { Field, FieldContent, FieldDescription, FieldLabel } from "@/registry/erbium/ui/field";
import { Switch } from "@/registry/erbium/ui/switch";

export default function FieldSwitch() {
  return (
    <div className="w-full max-w-md">
      <Field orientation="horizontal">
        <FieldContent>
          <FieldLabel>Multi-factor authentication</FieldLabel>
          <FieldDescription>
            Enable multi-factor authentication. If you do not have a two-factor device, you can use
            a one-time code sent to your email.
          </FieldDescription>
        </FieldContent>
        <Switch />
      </Field>
    </div>
